                e['skills']=[(s.get('name'),s.get('path'),len(s.get('content') or '')) for s in a.get('skills',[])]
                e['rendered_len']=sum(len(r.get('content','')) if isinstance(r.get('content'),str) else 0 for r in d.get('rendered') or [])
